const clave = "cuaderno-tema";

export function guardarTema(almacen, tema) {
  almacen.setItem(clave, JSON.stringify({ tema }));
}

export function leerTema(almacen) {
  try {
    const texto = almacen.getItem(clave);
    const guardado = texto === null ? null : JSON.parse(texto);
    return guardado?.tema === "oscuro" ? "oscuro" : "claro";
  } catch {
    return "claro";
  }
}

