const formulario = document.querySelector("#formulario");
const campo = document.querySelector("#texto");
const lista = document.querySelector("#tareas");
const resumen = document.querySelector("#resumen");
let tareas = [{ id: 1, texto: "Repasar el DOM", completada: false }];
let siguienteId = 2;

function dibujar() {
  lista.replaceChildren();
  for (const tarea of tareas) {
    const fila = document.createElement("li");
    const etiqueta = document.createElement("label");
    const control = document.createElement("input");
    control.type = "checkbox";
    control.checked = tarea.completada;
    control.addEventListener("change", () => {
      tareas = tareas.map((item) => item.id === tarea.id
        ? { ...item, completada: control.checked }
        : item);
      actualizarResumen();
    });
    etiqueta.append(control, tarea.texto);
    fila.append(etiqueta);
    lista.append(fila);
  }
  actualizarResumen();
}

function actualizarResumen() {
  const completadas = tareas.filter((tarea) => tarea.completada).length;
  resumen.textContent = completadas + " de " + tareas.length + " completadas";
}

formulario.addEventListener("submit", (event) => {
  event.preventDefault();
  const texto = campo.value.trim();
  if (!texto) return;
  tareas = [...tareas, { id: siguienteId++, texto, completada: false }];
  formulario.reset();
  dibujar();
  campo.focus();
});

dibujar();

function* paginas(temas, cantidad) {
  if (!Number.isInteger(cantidad) || cantidad < 1) {
    throw new RangeError("El tamaño debe ser un entero positivo");
