export function crearDuracion(minutos) {
  if (!Number.isInteger(minutos) || minutos < 0) {
    throw new RangeError("Usa un número entero no negativo.");
  }

  return Object.freeze({
    minutos,
    texto() {
      return `${Math.floor(minutos / 60)} h ${minutos % 60} min`;
    },
  });
}

