import React, { useEffect, useState } from 'react';

const datos = {
  html: { cursos: ['Semántica', 'Formularios'] },
  css: { cursos: ['Grid', 'Flexbox'] },
};

export default function App() {
  const [tema, setTema] = useState('html');
  const [estado, setEstado] = useState({ tipo: 'carga' });

  useEffect(() => {
    const control = new AbortController();
    const recurso = 'data:application/json,' + encodeURIComponent(JSON.stringify(datos[tema]));
    setEstado({ tipo: 'carga' });

    async function cargar() {
      try {
        const respuesta = await fetch(recurso, { signal: control.signal });
        if (!respuesta.ok) throw new Error('La petición falló');

        const contenido = await respuesta.json();
        if (!Array.isArray(contenido.cursos) || !contenido.cursos.every(x => typeof x === 'string')) {
          throw new Error('Respuesta inesperada');
        }
        if (!control.signal.aborted) setEstado({ tipo: 'datos', lista: contenido.cursos });
      } catch (error) {
        if (!control.signal.aborted) setEstado({ tipo: 'error', mensaje: error.message });
      }
    }

    cargar();
    return () => control.abort();
  }, [tema]);

  return (
    <main>
      <h1>Cursos</h1>
      <button onClick={() => setTema('html')}>HTML</button>
      <button onClick={() => setTema('css')}>CSS</button>
      {estado.tipo === 'carga' && <p role="status">Cargando…</p>}
      {estado.tipo === 'error' && <p role="alert">{estado.mensaje}</p>}
      {estado.tipo === 'datos' && <ul>{estado.lista.map(curso => <li key={curso}>{curso}</li>)}</ul>}
    </main>
  );
}

