let total = 0;
const escuchas = new Set();

function subscribe(aviso) {
  escuchas.add(aviso);
  return () => escuchas.delete(aviso);
}

function getSnapshot() {
  return total;
}

function incrementar() {
  total += 1;
  for (const aviso of [...escuchas]) aviso();
}

