}

import { useOptimistic, useState, useTransition } from 'react';

const esperar = ms => new Promise(resolve => setTimeout(resolve, ms));

export default function App() {
  const [confirmado, setConfirmado] = useState(0);
  const [fallar, setFallar] = useState(false);
  const [mensaje, setMensaje] = useState('');
  const [pendiente, startTransition] = useTransition();
  const [visible, sumarOptimista] = useOptimistic(
    confirmado,
    (total, cantidad) => total + cantidad,
  );

  function guardar() {
    setMensaje('');
    startTransition(async () => {
      sumarOptimista(1);
      await esperar(450);
      startTransition(() => {
        if (fallar) {
          setMensaje('No se guardó. Puedes intentarlo de nuevo.');
        } else {
          setConfirmado(total => total + 1);
          setMensaje('Guardado');
        }
      });
    });
  }

  return (
    <main>
      <p>Lecturas: {visible}</p>
      <button disabled={pendiente} onClick={guardar}>Guardar lectura</button>
      <label>
        <input type="checkbox" checked={fallar} disabled={pendiente}
          onChange={evento => setFallar(evento.target.checked)} />
        Simular un fallo
      </label>
      <p role="status">{pendiente ? 'Guardando…' : mensaje}</p>
    </main>
  );
}

