export default function App() {
    const [peticion, setPeticion] = useState(null);
    const [pendiente, setPendiente] = useState(false);
    const entregar = useRef(null);

    function preparar() {
        const resultado = new Promise((resolve) => {
            entregar.current = resolve;
        });
        setPeticion(resultado);
        setPendiente(true);
    }

    function resolver() {
        entregar.current?.("React");
        entregar.current = null;
        setPendiente(false);
    }

    return (
        <main>
            <h1>Selección de repaso</h1>
            <button disabled={pendiente} onClick={preparar}>Preparar selección</button>
            <button disabled={!pendiente} onClick={resolver}>Entregar selección</button>
            <Suspense fallback={<p role="status">Preparando temas…</p>}>
                {peticion ? <Seleccion peticion={peticion} /> : <p>Sin selección</p>}
            </Suspense>
        </main>
    );
}

