public class Main {
  static class Historial {
    private final Deque<String> anteriores = new ArrayDeque<>();
    private final Deque<String> siguientes = new ArrayDeque<>();
    private String actual = "";

    void editar(String nuevo) {
      anteriores.addLast(actual);
      actual = nuevo;
      siguientes.clear();
    }

    void deshacer() {
      String previo = anteriores.pollLast();
      if (previo == null) return;
      siguientes.addLast(actual);
      actual = previo;
    }

    void rehacer() {
      String siguiente = siguientes.pollLast();
      if (siguiente == null) return;
      anteriores.addLast(actual);
      actual = siguiente;
    }
  }

  public static void main(String[] args) {
    var historial = new Historial();
    historial.editar("Apunte");
    historial.editar("Apunte de Java");
    historial.deshacer();
    System.out.println(historial.actual);
    historial.rehacer();
    System.out.println(historial.actual);
    historial.deshacer();
    historial.editar("Apunte de SQL");
    historial.rehacer();
    System.out.println(historial.actual);
