public class Main {
    sealed interface Resultado permits Guardada, Rechazada {}
    record Guardada(int id, int minutos) implements Resultado {}
    record Rechazada(String motivo) implements Resultado {}

    static Resultado guardar(int minutos) {
        if (minutos < 1) return new Rechazada("La duración debe ser positiva");
        return new Guardada(12, minutos);
    }

    static String resumen(Resultado resultado) {
        return switch (resultado) {
            case Guardada(int id, int minutos) -> "Sesión " + id + ": " + minutos + " min";
            case Rechazada(String motivo) -> motivo;
        };
    }

    public static void main(String[] args) {
        System.out.println(resumen(guardar(25)));
        System.out.println(resumen(guardar(0)));
    }
}

