enum class Error { Sintaxis, Rango };

std::variant<int, Error> leerMinutos(std::string_view entrada) {
  if (entrada.empty()) return Error::Sintaxis;

  int total = 0;
  auto fin = entrada.data() + entrada.size();
  auto resultado = std::from_chars(entrada.data(), fin, total);
  if (resultado.ec == std::errc::result_out_of_range) return Error::Rango;
  if (resultado.ec != std::errc{} || resultado.ptr != fin) return Error::Sintaxis;
  if (total < 1 || total > 240) return Error::Rango;
  return total;
}

int main() {
  for (std::string_view texto : {"15", "12min", "900000000000", "0"}) {
    auto resultado = leerMinutos(texto);
    std::cout << texto << ": ";
    if (const int* total = std::get_if<int>(&resultado)) {
      std::cout << *total << " min\n";
    } else {
      std::cout << (std::get<Error>(resultado) == Error::Rango
                    ? "fuera de rango" : "formato incorrecto") << '\n';
    }
  }
}

