BEGIN IMMEDIATE;

WITH orden(origen, destino, importe) AS (VALUES (1, 2, 20)),
transferible AS MATERIALIZED (
    SELECT p.origen, p.destino, p.importe
    FROM orden AS p
    JOIN cuentas AS a ON a.id = p.origen
    JOIN cuentas AS b ON b.id = p.destino
    WHERE a.saldo >= p.importe AND p.importe > 0 AND p.origen <> p.destino
)
UPDATE cuentas
SET saldo = saldo + CASE WHEN id = (SELECT origen FROM transferible)
    THEN -(SELECT importe FROM transferible)
    ELSE (SELECT importe FROM transferible)
END
WHERE id IN (
    SELECT origen FROM transferible UNION ALL SELECT destino FROM transferible
);

COMMIT;

SELECT id, saldo FROM cuentas ORDER BY id;

