WITH estudio(id, dia, minutos) AS (
  VALUES (1, '2026-11-02', 15), (2, '2026-11-03', 20),
         (3, '2026-11-03', 25), (4, '2026-11-04', 10)
)
SELECT id, minutos,
       sum(minutos) OVER (
         ORDER BY dia, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS por_sesion,
       sum(minutos) OVER (
         ORDER BY dia RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS por_dia
FROM estudio
ORDER BY dia, id;

